/// <summary>
/// LocationType: PHYSICAL, VIRTUAL, CONSIGNMENT_OWN, CONSIGNMENT_VENDOR or TRANSIT. VerifyOnly: the
/// line is confirmed present, not counted (e.g. in transit) - decided here.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountLineAttributeRow
{
    real    lineNumber;
    str     locationType;
    str     owner;
    boolean verifyOnly;

}

Method.Source:
[DataMemberAttribute('LineNumber')]
public real parmLineNumber(real _value = lineNumber)
{
    lineNumber = _value;
    return lineNumber;
}

[DataMemberAttribute('LocationType')]
public str parmLocationType(str _value = locationType)
{
    locationType = _value;
    return locationType;
}

[DataMemberAttribute('Owner')]
public str parmOwner(str _value = owner)
{
    owner = _value;
    return owner;
}

[DataMemberAttribute('VerifyOnly')]
public boolean parmVerifyOnly(boolean _value = verifyOnly)
{
    verifyOnly = _value;
    return verifyOnly;
}
